import { describe, expect, it, vi } from 'vitest';
import { AlbumDetails, MusicBrainzClient } from '../src/api/musicbrainz';
import type { HttpRequest } from '../src/api/types';
import release from './fixtures/musicbrainz_release.json';
import search from './fixtures/musicbrainz_search.json';

// Generated by the Python CLI's MusicBrainzClient from the same data.
const CLI_ABBEY_ROAD_NOTE =
	'---\ncollection: "[[Albums]]"\ntags:\n  - rock\n---\n\n## Links\nhttps://musicbrainz.org/release/a3b7f0e5-7e7d-4e4f-8e5c-1a2b3c4d5e6f\n\n## Description\nBy [[The Beatles]]. Released by [[Apple Records]].\n';
const CLI_COMPILATION_NOTE =
	'---\ncollection: "[[Albums]]"\ntags:\n  - compilation\n  - spokenword\n  - rock\n  - progressive-rock\n  - shoegaze\n---\n\n## Links\nhttps://musicbrainz.org/release/a3b7f0e5-7e7d-4e4f-8e5c-1a2b3c4d5e6f\n\n## Description\nBy [[The Beatles]]. Released by [[Independent]].\n';

const ABBEY_ROAD: AlbumDetails = {
	id: 'a3b7f0e5-7e7d-4e4f-8e5c-1a2b3c4d5e6f',
	title: 'Abbey Road',
	artist: 'The Beatles',
	date: '1969-09-26',
	label: 'Apple Records',
	primaryType: 'Album',
	secondaryTypes: [],
	tags: ['rock'],
	disambiguation: '',
};

function setup(...responses: unknown[]) {
	const request = vi.fn<(req: HttpRequest) => Promise<unknown>>();
	for (const r of responses) request.mockResolvedValueOnce(r);
	const sleep = vi.fn((_ms: number) => Promise.resolve());
	let clock = 10_000;
	const now = () => clock;
	const client = new MusicBrainzClient(request, 'MediaNotes/test ( https://example.com )', sleep, now);
	return { client, request, sleep, tick: (ms: number) => (clock += ms) };
}

describe('MusicBrainzClient.search', () => {
	it('searches official albums with a User-Agent and normalizes results', async () => {
		const { client, request } = setup(search);
		const results = await client.search('Abbey Road: (Remastered)');

		const call = request.mock.calls[0]?.[0];
		const url = new URL(call?.url ?? '');
		expect(url.origin + url.pathname).toBe('https://musicbrainz.org/ws/2/release');
		expect(url.searchParams.get('query')).toBe(
			'release:(Abbey Road\\: \\(Remastered\\)) AND status:official AND primarytype:album',
		);
		expect(url.searchParams.get('fmt')).toBe('json');
		expect(url.searchParams.get('limit')).toBe('25');
		expect(call?.headers?.['User-Agent']).toBe('MediaNotes/test ( https://example.com )');

		expect(results).toEqual([
			{
				id: 'a3b7f0e5-7e7d-4e4f-8e5c-1a2b3c4d5e6f',
				title: 'Abbey Road',
				year: '1969',
				overview: 'The Beatles · Album',
				thumbnailUrl:
					'https://coverartarchive.org/release/a3b7f0e5-7e7d-4e4f-8e5c-1a2b3c4d5e6f/front-250',
			},
			{
				id: 'different-release-id',
				title: 'Abbey Road Sessions',
				year: '2019',
				overview: 'Paul McCartney & Wings · Album/Compilation/Live · 50th anniversary',
				thumbnailUrl: 'https://coverartarchive.org/release/different-release-id/front-250',
			},
		]);
	});

	it('handles an empty response', async () => {
		const { client } = setup({});
		expect(await client.search('nothing')).toEqual([]);
	});

	it('waits so requests are at least a second apart', async () => {
		const { client, sleep, tick } = setup(search, release, release);
		await client.search('Abbey Road');
		expect(sleep).not.toHaveBeenCalled();
		tick(300);
		await client.getDetails('a');
		expect(sleep).toHaveBeenCalledWith(700);
		tick(1500);
		await client.getDetails('a');
		expect(sleep).toHaveBeenCalledTimes(1);
	});
});

describe('MusicBrainzClient.getDetails', () => {
	it('requests artists, labels, release group and tags', async () => {
		const { client, request } = setup(release);
		const details = await client.getDetails('a3b7f0e5-7e7d-4e4f-8e5c-1a2b3c4d5e6f');
		const url = new URL(request.mock.calls[0]?.[0].url ?? '');
		expect(url.pathname).toBe('/ws/2/release/a3b7f0e5-7e7d-4e4f-8e5c-1a2b3c4d5e6f');
		expect(url.searchParams.get('inc')).toBe('artists+labels+release-groups+tags');
		// Same normalized details the CLI produces from this release.
		expect(details).toEqual(ABBEY_ROAD);
	});

	it('keeps the top five tags with more than five votes, most voted first', async () => {
		const tags = [3, 9, 6, 20, 7, 8, 12].map((count, i) => ({ name: `t${i}`, count }));
		const { client } = setup({ ...release, 'release-group': { ...release['release-group'], tags } });
		expect((await client.getDetails('x')).tags).toEqual(['t3', 't6', 't1', 't5', 't4']);
	});

	it('falls back to release tags, then to defaults', async () => {
		const { client } = setup({
			id: 'x',
			'release-group': { tags: [] },
			tags: [{ name: 'jazz', count: 6 }],
		});
		expect(await client.getDetails('x')).toEqual({
			id: 'x',
			title: 'Unknown',
			artist: 'Various Artists',
			date: '',
			label: 'Independent',
			primaryType: 'Album',
			secondaryTypes: [],
			tags: ['jazz'],
			disambiguation: '',
		});
	});
});

describe('MusicBrainzClient notes', () => {
	const { client } = setup();

	it('matches the CLI note and filename', () => {
		expect(client.formatNote(ABBEY_ROAD)).toBe(CLI_ABBEY_ROAD_NOTE);
		expect(client.getFilename(ABBEY_ROAD)).toBe('The Beatles - Abbey Road (1969).md');
	});

	it('matches the CLI for secondary types, mapped tags and no date', () => {
		const album: AlbumDetails = {
			...ABBEY_ROAD,
			secondaryTypes: ['Compilation', 'Spokenword'],
			tags: ['classic rock', 'prog rock', 'Shoegaze'],
			label: 'Independent',
			date: '',
		};
		expect(client.formatNote(album)).toBe(CLI_COMPILATION_NOTE);
		expect(client.getFilename(album)).toBe('The Beatles - Abbey Road (TBD).md');
		expect(client.getTitleAndYear(album)).toEqual({ title: 'Abbey Road', year: null });
	});

	it('uses the Cover Art Archive front cover', () => {
		expect(client.getPosterUrl(ABBEY_ROAD)).toBe(
			'https://coverartarchive.org/release/a3b7f0e5-7e7d-4e4f-8e5c-1a2b3c4d5e6f/front',
		);
	});
});
